import type { Block, CollectionConfig, Field, Plugin } from 'payload'

/**
 * Ukrainian labels for collections generated by third-party plugins
 * (payload-auth, form-builder, search, MCP) that expose no translation API —
 * their labels/descriptions are hardcoded English strings. This plugin runs
 * last and rewrites those strings in the sanitized config.
 *
 * Only fields explicitly listed in the map are touched; everything else is
 * left as the plugin produced it.
 */

type FieldMap = Record<
  string,
  {
    blocks?: Record<string, { fields?: FieldMap; labels?: { plural: string; singular: string } }>
    description?: string
    fields?: FieldMap
    label?: string
    labels?: { plural: string; singular: string }
    options?: Record<string, string>
  }
>

type CollectionMap = {
  description?: string
  fields?: FieldMap
  group?: string
  labels?: { plural: string; singular: string }
}

