/** English tab labels inside plugin-generated collections. */
const tabLabelMap: Record<string, string> = {
  Prompts: 'Промпти',
  Resources: 'Ресурси',
  Tools: 'Інструменти',
}

const applyFieldMap = (fields: Field[], map: FieldMap): void => {
  for (const field of fields) {
    if (field.type === 'tabs') {
      for (const tab of field.tabs) {
        if (typeof tab.label === 'string' && tabLabelMap[tab.label]) {
          tab.label = tabLabelMap[tab.label]
        }
        applyFieldMap(tab.fields, map)
      }
      continue
    }

    if (field.type === 'row' || field.type === 'collapsible') {
      applyFieldMap(field.fields, map)
      continue
    }

    if (!('name' in field) || !field.name) continue
    const entry = map[field.name]
    if (!entry) continue

    if (entry.label !== undefined) field.label = entry.label
    if (entry.labels && (field.type === 'array' || field.type === 'blocks')) {
      field.labels = entry.labels
    }
    if (entry.description !== undefined) {
      field.admin = { ...field.admin, description: entry.description }
    }
    if (entry.options && 'options' in field && Array.isArray(field.options)) {
      field.options = field.options.map((option) => {
        if (typeof option === 'string') {
          return entry.options![option] ? { label: entry.options![option], value: option } : option
        }
        const translated = entry.options![option.value]
        return translated ? { ...option, label: translated } : option
      })
    }
    if (entry.fields && 'fields' in field && Array.isArray(field.fields)) {
      applyFieldMap(field.fields, entry.fields)
    }
    if (entry.blocks && field.type === 'blocks' && Array.isArray(field.blocks)) {
      for (const block of field.blocks as Block[]) {
        const blockEntry = entry.blocks[block.slug]
        if (!blockEntry) continue
        if (blockEntry.labels) block.labels = blockEntry.labels
        if (blockEntry.fields) applyFieldMap(block.fields, blockEntry.fields)
      }
    }
  }
}

const applyCollectionMap = (collection: CollectionConfig, map: CollectionMap): void => {
  if (map.labels) collection.labels = map.labels
  if (map.description !== undefined || map.group !== undefined) {
    collection.admin = {
      ...collection.admin,
      ...(map.description !== undefined && { description: map.description }),
      ...(map.group !== undefined && { group: map.group }),
    }
  }
  if (map.fields) applyFieldMap(collection.fields, map.fields)
}

export const ukrainianAdmin: Plugin = (config) => {
  for (const collection of config.collections ?? []) {
    const map = collectionMap[collection.slug]
    if (map) applyCollectionMap(collection, map)

    // The payload-auth invite button is hardcoded English — swap in our
    // Ukrainian version (it reuses the same server endpoints).
    if (collection.slug === 'users') {
      const description = collection.admin?.components?.Description
      if (
        description &&
        typeof description === 'object' &&
        'path' in description &&
        typeof description.path === 'string' &&
        description.path.includes('AdminInviteButton')
      ) {
        description.path = '@/components/admin/InviteUserButton#InviteUserButton'
      }
    }
  }

  return config
}
